
(async () => {
  // V23: this file contains ONLY the user's animation data.
  // No mesh, character, axe, weapon, or replacement model from the FBX is added to the scene.
  const ATTACK_GZ = "";
  const SOURCE_SHA256 = "d4b7b530b748baa764a0b00be1a72f87564aace879e970c0c26e189df1726e64";

  const hint = document.getElementById("attackHint");
  const status = document.getElementById("status");
  const canvas = document.getElementById("c");
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  async function gunzipB64(s) {
    const bin=atob(s), raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) raw[i]=bin.charCodeAt(i);
    const ds=new DecompressionStream("gzip");
    return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
  }

  async function importFirst(urls) {
    let last;
    for(const u of urls) {
      try { return await window.__LOCAL_IMPORT(u); }
      catch(e) { last=e; }
    }
    throw last || new Error("Falha ao carregar FBXLoader.");
  }

  async function waitGame() {
    for(let i=0;i<900;i++) {
      const g=window.gameReview;
      if (
        g?.trueFirstPerson?.model &&
        g?.trueFirstPerson?.visibleRoot &&
        g?.trueFirstPerson?.eyeSocket &&
        g?.trueFirstPerson?.socket &&
        window.gameRightHand
      ) return g;
      await sleep(20);
    }
    throw new Error("Corpo/rig atual não ficou disponível.");
  }

  function prepareFullBodyClip(THREE, sourceClip) {
    const clip=sourceClip.clone();

    // FULL BODY: hips, spine, head, BOTH arms, BOTH legs and feet.
    // Finger animation is intentionally left to the existing grip systems:
    // right fingers keep gripping the axe; left fingers keep gripping the torch.
    clip.tracks=clip.tracks.filter(track => {
      const n=track.name;

      if (/\.scale$/i.test(n)) return false;

      // Preserve every bone rotation from the user's animation.
      if (/\.quaternion$/i.test(n)) {
        if (/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n)) return false;
        return true;
      }

      // Root/hips translation from Mixamo can drag the player across the map.
      // The existing player controller remains responsible for world position.
      // Rotational hip/leg motion is still kept above.
      return false;
    });

    clip.name="Standing Melee Attack Downward - FULL BODY";
    clip.resetDuration();
    return clip;
  }

  try {
    const game=await waitGame();
    const tfp=game.trueFirstPerson;

    const [THREE, loaderMod, attackBuffer] = await Promise.all([
      importFirst([
        window.FLORESTA_MODULES.three,
        window.FLORESTA_MODULES.three
      ]),
      importFirst([
        window.FLORESTA_MODULES.FBXLoader,
        window.FLORESTA_MODULES.FBXLoader
      ]),
      gunzipB64(ATTACK_GZ)
    ]);

    const {FBXLoader}=loaderMod;

    // Parse only to extract animation data. The parsed FBX object is NEVER added to scene.
    const parsed=new FBXLoader().parse(attackBuffer,"");
    if(!parsed.animations?.length) {
      throw new Error("O FBX enviado não contém animação.");
    }

    const fullClip=prepareFullBodyClip(THREE,parsed.animations[0]);
    if(!fullClip.tracks.length) {
      throw new Error("A animação não possui tracks compatíveis.");
    }

    // Dedicated animation mixer is intentionally evaluated AFTER the current
    // true-first-person controller. That lets the uploaded attack drive the
    // WHOLE current body, including the arm that holds the torch.
    const attackMixer=new THREE.AnimationMixer(tfp.model);
    const action=attackMixer.clipAction(fullClip,tfp.model);
    action.setLoop(THREE.LoopOnce,1);
    action.clampWhenFinished=true;
    action.enabled=true;
    action.setEffectiveWeight(1);
    action.setEffectiveTimeScale(1.0);

    let active=false;
    let activeWeapon=null;
    let finishTimer=null;
    let impactTimer=null;
    let swingId=0;
    let cooldownUntil=0;
    let lastFrameTime=performance.now();

    function axeReady() {
      return window.gameRightHand?.current==="axe";
    }

    function hammerReady() {
      return window.gameRightHand?.current==="hammer";
    }

    function blocked() {
      return !!(
        window.gameInventory?.isOpen ||
        window.gameCraft?.active ||
        document.body.classList.contains("crafting-active")
      );
    }

    function updateHint() {
      if(!hint) return;
      if(window.gameRightHand?.current==="hammer")return;
      hint.style.opacity=axeReady()&&!blocked() ? "1" : "0";
    }

    // Existing torch follows the already-existing left hand socket.
    // No new torch is created and its current look/material/light are untouched.
    const torchOffset=new THREE.Vector3(0,.06*.65,0);
    const bodyYawQ=new THREE.Quaternion();
    const worldSocket=new THREE.Vector3();
    const eyePos=new THREE.Vector3();

    function resyncExistingItemsAndCamera() {
      tfp.visibleRoot.updateMatrixWorld(true);

      // Existing axe -> current animated right hand.
      window.gameRightHand?.sync?.();

      // Existing torch -> current animated left hand.
      if(game.torchRoot && game.isEquipped?.()) {
        tfp.socket.getWorldPosition(worldSocket);
        bodyYawQ.setFromAxisAngle(
          new THREE.Vector3(0,1,0),
          game.player.bodyYaw ?? game.player.yaw
        );
        game.torchRoot.position.copy(worldSocket).sub(
          torchOffset.clone().applyQuaternion(bodyYawQ)
        );
      }

      // Camera stays at the anatomical eyes while the WHOLE body performs
      // the attack. Its look direction remains controlled by the player.
      tfp.eyeSocket.getWorldPosition(eyePos);
      game.camera.position.copy(eyePos);
      game.camera.updateMatrixWorld(true);
    }

    // The existing update chain is:
    // base locomotion -> TFP look/torch IK -> existing axe grip.
    // V23 adds the user's full-body animation AFTER all of that.
    const previousUpdate=window.__updateAnimatedAvatar;
    window.__updateAnimatedAvatar=(...args)=>{
      previousUpdate?.(...args);

      const now=performance.now();
      const dt=Math.min(.05,Math.max(0,(now-lastFrameTime)/1000));
      lastFrameTime=now;

      if(active) {
        attackMixer.update(dt);
        resyncExistingItemsAndCamera();
      }
    };

    function finishAttack() {
      const finishedWeapon=activeWeapon;

      action.stop();
      attackMixer.stopAllAction();

      active=false;
      activeWeapon=null;

      window.gameAttack.active=false;

      // The normal controller resumes on the next frame.
      window.gameRightHand?.sync?.();

      if(status) {
        status.textContent=
          finishedWeapon==="hammer"
            ? "Martelo pronto"
            : "Machado pronto para atacar";
      }
    }

    function startWeaponAttack(kind="axe") {
      const now=performance.now();

      const ready=
        kind==="hammer"
          ? hammerReady()
          : axeReady();

      if(
        active ||
        now<cooldownUntil ||
        !ready ||
        blocked()
      )return false;

      active=true;
      activeWeapon=kind;

      window.gameAttack.active=true;

      action.stop();
      action.reset();
      action.enabled=true;
      action.setEffectiveWeight(1);

      // A hammer strike is a touch heavier/faster on the downstroke but still
      // uses the proven full-body skeleton animation instead of procedural IK.
      const speed=
        kind==="hammer"
          ? 1.08
          : 1.0;

      action.setEffectiveTimeScale(speed);
      action.play();

      const duration=
        Math.max(
          .20,
          fullClip.duration/speed
        );

      cooldownUntil=
        now+
        duration*1000*.82;

      const thisSwing=++swingId;

      if(status) {
        status.textContent=
          kind==="hammer"
            ? "Martelando • animação corpo inteiro"
            : "Ataque corpo inteiro • animação FBX";
      }

      clearTimeout(impactTimer);

      impactTimer=setTimeout(()=>{
        if(
          active &&
          thisSwing===swingId &&
          activeWeapon===kind
        ){
          if(kind==="hammer"){
            let position=null;

            try{
              const p=
                window.gameHammer
                  ?.headWorld?.();

              if(p){
                position={
                  x:p.x,
                  y:p.y,
                  z:p.z
                };
              }
            }catch{}

            window.dispatchEvent(
              new CustomEvent(
                "game:hammer-impact",
                {
                  detail:{
                    swingId:thisSwing,
                    source:"player-hammer",
                    position
                  }
                }
              )
            );
          }else{
            window.dispatchEvent(
              new CustomEvent(
                "game:axe-impact",
                {
                  detail:{
                    swingId:thisSwing,
                    source:"player-axe"
                  }
                }
              )
            );
          }
        }
      },duration*1000*.50);

      clearTimeout(finishTimer);

      finishTimer=setTimeout(
        finishAttack,
        duration*1000+35
      );

      return true;
    }

    function attack() {
      return startWeaponAttack("axe");
    }

    function hammerAttack() {
      return startWeaponAttack("hammer");
    }

    // Click/touch only triggers the animation when the EXISTING axe is equipped.
    canvas?.addEventListener("pointerdown",e=>{
      // V46 MOBILE:
      // Touch on the canvas is reserved for camera-look. Attacks on phones
      // use the dedicated ATACAR button, so dragging the view never swings.
      if(e.pointerType!=="mouse") return;
      if(e.button!==0) return;

      // First desktop click is reserved for Pointer Lock.
      if(document.pointerLockElement !== canvas) return;
      // V168O: the old local `attack()` always drives the AXE FBX and ignores
      // wrappers installed on window.gameAttack.attack. Route the spear here.
      if(window.gameRightHand?.current === 'pickaxe'){window.gamePrimitive?.attack('pickaxe');return;}
      if(window.gameRightHand?.current === 'spear'){
        window.gamePrimitive?.beginSpear?.();
        return;
      }
      attack();
    },true);

    window.gameAttack={
      active:false,
      attack,
      hammerAttack,
      get weapon(){return activeWeapon;},
      get duration(){return fullClip.duration;},
      get clipName(){return fullClip.name;},
      get trackCount(){return fullClip.tracks.length;},
      source:"Standing Melee Attack Downward.fbx",
      sourceSha256:SOURCE_SHA256,
      mode:"full-body-existing-character"
    };

    setInterval(updateHint,180);
    updateHint();

    if(status) {
      status.textContent=
        `Ataque corpo inteiro carregado • ${fullClip.tracks.length} tracks • clique para bater`;
    }
  } catch(err) {
    console.error("Ataque corpo inteiro:",err);
    if(status) {
      status.textContent+=" • ataque indisponível: "+String(err?.message||err);
    }
  }
})();
